-- Native module registry; uses the existing common_fx script mapping.
local platformRequire=require
local loaders,loaded,loading={},{},{}
local function resolve(name)
 if loaded[name]~=nil then return loaded[name] end
 local loader=loaders[name]
 if not loader then return platformRequire(name) end
 assert(not loading[name],'Cyclic native module: '..name)
 loading[name]=true
 local result=loader(resolve)
 assert(result~=nil,'Native module returned nil: '..name)
 loading[name]=nil;loaded[name]=result
 return result
end
